var e={preflight:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Yazıcının baskıya başlamaya hazır olup olmadığını kontrol eden hızlı, salt-okunur bir denetim.`}},refresh:{t:0,b:{t:2,i:[{t:3}],s:`Yeniden kontrol et`}},checking:{t:0,b:{t:2,i:[{t:3}],s:`Kontrol ediliyor...`}},ready:{t:0,b:{t:2,i:[{t:3}],s:`Baskıya hazır`}},notReady:{t:0,b:{t:2,i:[{t:3}],s:`Baskıya hazır değil`}},checks:{unreachable:{fail:{t:0,b:{t:2,i:[{t:3}],s:`Yazıcıya erişilemiyor`}}},klippy:{pass:{t:0,b:{t:2,i:[{t:3}],s:`Klipper hazır`}},fail:{t:0,b:{t:2,i:[{t:3,v:`Klipper hazır değil (durum: `},{t:4,k:`state`},{t:3,v:`)`}]}}},idle:{pass:{t:0,b:{t:2,i:[{t:3}],s:`Devam eden baskı yok`}},fail:{t:0,b:{t:2,i:[{t:3,v:`Zaten bir baskı çalışıyor (`},{t:4,k:`state`},{t:3,v:`)`}]}}},homed:{pass:{t:0,b:{t:2,i:[{t:3}],s:`Tüm eksenler eve döndü`}},fail:{t:0,b:{t:2,i:[{t:3,v:`Eksenler eve dönmedi (`},{t:4,k:`axes`},{t:3,v:`); baskı başlatma genellikle önce eve döner`}]}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Rehber`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Baskı öncesi kontrol rehberi`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Kapat`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`Baskı öncesi kontrol nedir?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Yazıcının başlamaya hazır olup olmadığına salt-okunur bir bakış: asla bir şeyi hareket ettirmez veya değiştirmez, yalnızca rapor verir. Kesin engeller sonucu kırmızıya çevirir; uyarılar bilgi verir ama engellemez.`}}},checks:{title:{t:0,b:{t:2,i:[{t:3}],s:`Neleri kontrol eder`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Klipper hazır mı (kapatılmamış veya hatasız), zaten bir baskı çalışıyor mu ve eksenler eve döndü mü (bilgilendiricidir, çünkü baskı başlatma genellikle önce eve döner).`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Sözlük`}}}},glossary:{klippyState:{term:{t:0,b:{t:2,i:[{t:3}],s:`Klipper durumu`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Klipper'ın kendi durumu - 'ready' bağlı ve boşta olduğu anlamına gelir; 'shutdown' veya 'error' temizlenene kadar baskı yapamayacağı anlamına gelir.`}}},homing:{term:{t:0,b:{t:2,i:[{t:3}],s:`Eve dönüş`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Yazıcının araç kafasının nerede olduğunu bilmesi için her ekseni endstop'una hareket ettirme. Çoğu baskı başlatma rutini otomatik olarak eve döner.`}}}}}}};export{e as default};